import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long rem = x;
        long best_num = 0;
        long best_den = 1;

        for (long b = 1; b <= n; b++) {
            long a = Math.max(x * b / y - 10, 0);
            for (int j = 0; j < 20; j++) {
                long candidate_a = a + j;
                long diff = Math.abs(x * b - candidate_a * y);
                if (rem * b > diff * best_den) {
                    rem = diff;
                    best_num = candidate_a;
                    best_den = b;
                } else if (rem * b == diff * best_den) {
                    if (best_den > b || (best_den == b && best_num > candidate_a)) {
                        best_num = candidate_a;
                        best_den = b;
                    }
                }
            }
        }
        System.out.println(best_num + "/" + best_den);
        sc.close();
    }
}
